"OLAYLAR_ORTACAG_ORTADOGU:0701-01-01:0":{"b": ["Bataille de Dayr al-Djamâdjim, où Hadjdjâdj bat Abd al-Rahmân b. al-Ash'ath (djoumâdâ II 82 / juillet 701).", "39040fea"], "d": ["Bataille de Dayr al-Djamâdjim, où Hadjdjâdj bat Abd al-Rahmân b. al-Ash'ath (djoumâdâ II 82 / juillet 701).", "39040fea"]},
"OLAYLAR_ORTACAG_ORTADOGU:0705-01-02:0":{"b": ["Walîd Ier devient calife (86/705) ; sous son règne, l'État omeyyade atteint sa plus grande extension.", "c848f25f"], "d": ["Walîd Ier devient calife (86/705) ; sous son règne, l'État omeyyade atteint sa plus grande extension.", "c848f25f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0711-07-26:0":{"b": ["Târik b. Ziyâd inflige une lourde défaite à l'armée wisigothe", "73301b6a"], "d": ["Au terme d'une bataille de huit jours entre les deux armées, l'armée wisigothe subit une lourde défaite (5 chawwâl 92 / 26 juillet 711) ; le lieu de la bataille se situe sur le Guadalete ou sur les rives du Barbate. On raconte que Târik conquit en peu de temps Malaga, Elvira, Cordoue et Tolède.", "12d78ad9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0712-06-20:0":{"b": ["Le raja du Sind Dâhir meurt face à Muhammed b. Qâsim ; Rûr (Arûr, Aror), Brahmanâbâd et Multan sont conquises", "bccf3c4f"], "d": ["Le souverain du Sind Dâhir, qui combattait le commandant omeyyade Muhammed b. Qâsim, mourut le 10 ramadan 93 / 20 juin 712 ; après cette bataille, Rûr (Arûr, Aror), Brahmanâbâd et Multan furent conquises et la totalité du Sind passa aux mains des Omeyyades.", "e213eabd"]},
"OLAYLAR_ORTACAG_ORTADOGU:0724-01-01:0":{"b": ["Hichâm b. Abd al-Malik devient calife (105/724) ; il règne jusqu'en 743.", "6288b8a9"], "d": ["Hichâm b. Abd al-Malik devient calife (105/724) ; il règne jusqu'en 743.", "6288b8a9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0732-03-03:0":{"b": ["L'armée omeyyade combat les Francs aux environs de Poitiers (Tours) (114/732).", "97262cdf"], "d": ["L'armée omeyyade combat les Francs aux environs de Poitiers (Tours) (114/732).", "97262cdf"]},
"OLAYLAR_ORTACAG_ORTADOGU:0744-12-07:0":{"b": ["Marwân II est proclamé calife", "f51a800a"], "d": ["Les personnes présentes proclamèrent Marwân calife (26 safar 127 / 7 décembre 744) ; la période du dernier calife omeyyade commença.", "1bc682b5"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-01-01:0":{"b": ["Marwân II soumet la Syrie ; il fait raser les murailles de Homs, Baalbek, Damas et Jérusalem", "468a2d97"], "d": ["Marwân, qui avait fait raser les murailles des villes de Syrie pour prévenir d'éventuelles révoltes, soumit la Syrie à l'été 128 (746).", "afc53641"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-09-22:0":{"b": ["Le chef kharidjite (ibadite) Tâlib al-Haqq, après le Hadramaout, prend Sanaa (San‘a) aux Omeyyades (129/746)", "d56ff983"], "d": ["Abdullah b. Yahyâ al-Hadramî (Tâlib al-Haqq) se révolta contre les Omeyyades avec le soutien des Ibadites d'Oman et se proclama calife ; après le Hadramaout, il s'empara de Sanaa (San‘a). Il marcha ensuite sur La Mecque et Médine, fut vaincu par les forces de Marwân II et fut tué près de Sanaa (130/748).", "a2697365"]},
"OLAYLAR_ORTACAG_ORTADOGU:0747-01-01:0":{"b": ["La révolution abbasside éclate ouvertement au Khorassan sous la direction d'Abou Muslim (129/747).", "92a5194c"], "d": ["La révolution abbasside éclate ouvertement au Khorassan sous la direction d'Abou Muslim (129/747).", "92a5194c"]},
