"OLAYLAR_ORTACAG_ORTADOGU:0750-01-16:0":{"b": ["Début de la bataille du Zâb ; Abdullah b. Ali bat Marwân II et disperse l'armée omeyyade.", "d9b81d02"], "d": ["Début de la bataille du Zâb ; Abdullah b. Ali bat Marwân II et disperse l'armée omeyyade.", "d9b81d02"]},
"OLAYLAR_ORTACAG_ORTADOGU:0750-01-25:0":{"b": ["Bataille du Grand Zâb : Marwân II subit une lourde défaite face aux Abbassides", "8d223056"], "d": ["La bataille, commencée le 2 djoumâdâ II 132 (16 janvier 750), se termina au matin du samedi 11 djoumâdâ II (25 janvier) par la lourde défaite de Marwân.", "cb560e7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0754-01-01:0":{"b": ["Mansûr devient calife (754-775) ; début de la période considérée comme celle du véritable fondateur du califat.", "cf491add"], "d": ["Mansûr devient calife (754-775) ; début de la période considérée comme celle du véritable fondateur du califat.", "cf491add"]},
